import logoVHN from '@src/assets/images/logo/vhn.png'
// ** Custom Components
import UILoader from '@components/ui-loader'
// import Spinner from '@components/spinner/Loading-spinner'
import {handleWarning} from '@src/views/pages/sweetalert'
// ** React Imports
import {Fragment, useContext, useEffect, useState } from 'react'
import { useNavigate, Link } from 'react-router-dom'

// ** Custom Hooks
import { useSkin } from '@hooks/useSkin'
import useJwt from '@src/auth/jwt/useJwt'

// ** Third Party Components
import { Coffee, Facebook, GitHub, HelpCircle, Mail, Twitter, X } from 'react-feather'
import { Controller, useForm } from 'react-hook-form'
import toast from 'react-hot-toast'
import { useDispatch } from 'react-redux'
// import axios from 'axios'

// ** Actions
import { handleLogin } from '@store/authentication'

// ** Context
import { AbilityContext } from '@src/utility/context/Can'

// ** Custom Components
import Avatar from '@components/avatar'
import InputPasswordToggle from '@components/input-password-toggle'

// ** Utils
// import { getHomeRouteForLoggedInUser } from '@utils'

// ** Reactstrap Imports
import { Alert, Button, CardText, CardTitle, Col, Form, Input, Label, Row, Spinner, UncontrolledTooltip } from 'reactstrap'

// ** Styles
import '@styles/react/pages/page-authentication.scss'

import { getMe } from '../../../redux/authentication'
import { getHomeRouteForLoggedInUser } from '../../../auth/utils'

const ToastContent = ({ t, name, role }) => {
  return (
    <div className='d-flex'>
      <div className='me-1'>
        <Avatar size='sm' color='success' icon={<Coffee size={12} />} />
      </div>
      <div className='d-flex flex-column'>
        <div className='d-flex justify-content-between'>
          <h6>{name}</h6>
          <X size={12} className='cursor-pointer' onClick={() => toast.dismiss(t.id)} />
        </div>
        <span>You have successfully logged in as an {role} user to Vuexy. Now you can start to explore. Enjoy!</span>
      </div>
    </div>
  )
}

const defaultValues = {

}

const Login = () => {
  const [block, setBlock] = useState(false)

  useEffect(() => {
    return () => setBlock(false)
  }, [])


  const Loader = () => {
    return (
      <Fragment>
        <Spinner color="primary" />
        <CardText className='mb-0 mt-1 text-white'>Vui lòng chờ hệ thống...</CardText>
      </Fragment>
    )
  }

  // ** Hooks
  const { skin } = useSkin()
  const dispatch = useDispatch()
  const navigate = useNavigate()
  const ability = useContext(AbilityContext)
  useEffect(() => {
    document.title = "VHN Group - Đăng nhập"
    return () => {
      document.title = "VHN Group - Hệ quản trị"
    }
  }, [])
  const {
    control,
    setError,
    handleSubmit,
    formState: { errors }
  } = useForm({ defaultValues })
  const illustration = skin === 'dark' ? 'login-v2-dark.svg' : 'login-v2.svg',
    source = require(`@src/assets/images/pages/${illustration}`).default

  const onSubmit = data => {  
    console.log(data.loginEmail, ' ', data.password)
    // const username = data.loginEmail
    // const password = data.password
    if (Object.values(data).every(field => field.length > 0)) {
      setBlock(true)
      const formdata = new FormData()
      formdata.append('username', data.loginEmail)
      formdata.append('password', data.password)
      useJwt
        .login(formdata)
        .then(async res => {
          const adminAbility = [{action: 'manage', subject: 'all'}]
          // const response = await axios.get('http://quayso.herokuapp.com/api/v1/user/me', {
          //   headers: {
          //     Authorization: `Bearer ${res.data.access_token}`
          //   }
          // })
          const data = { accessToken: res.data.access_token }
          dispatch(handleLogin(data))
          dispatch(getMe()).then(res => {
            console.log(res)
            navigate(getHomeRouteForLoggedInUser(res.payload.Role.name))
          })
          ability.update(adminAbility)
          
          // toast(t => (
          //   <ToastContent t={t} role={data.Role.name || 'admin'} name={data.name || data.username || data.Role.name || 'admin'} />
          // ))
        })
        .catch(err => {
          console.log(err)
          setBlock(false)
          handleWarning("Chú ý", "Vui lòng kiểm tra lại thông tin tài khoản.")
        })
    } else {
      for (const key in data) {
        if (data[key].length === 0) {
          setError(key, {
            type: 'manual'
          })
        }
      }
    }
  }

  return (
    <UILoader blocking={block} loader={<Loader />}>
      <div className='auth-wrapper auth-cover'>
        <Row className='auth-inner m-0'>
          <Link className='brand-logo' to='/' onClick={e => e.preventDefault()}>
            <img className='img-fluid' src={logoVHN} width="100" alt='Login Cover' />
            {/* <h2 className='brand-text text-primary ms-1'>VHN GROUP</h2> */}
          </Link>
          <Col className='d-none d-lg-flex align-items-center p-5' lg='8' sm='12'>
            <div className='w-100 d-lg-flex align-items-center justify-content-center px-5'>
              <img className='img-fluid' src={source} alt='Login Cover' />
            </div>
          </Col>
          <Col className='d-flex align-items-center auth-bg px-2 p-lg-5' lg='4' sm='12'>
            <Col className='px-xl-2 mx-auto' sm='8' md='6' lg='12'>
              <CardTitle tag='h2' className='fw-bold mb-1'>
                Hệ quản trị VHN Group
              </CardTitle>
              <CardText className='mb-2'>Hãy đang nhập để truy cập vào hệ quản trị</CardText>
              <Form className='auth-login-form mt-2' onSubmit={handleSubmit(onSubmit)} id='loginform'>
                <div className='mb-1'>
                  <Label className='form-label' for='login-email'>
                    Email
                  </Label>
                  <Controller
                    id='loginEmail'
                    name='loginEmail'
                    control={control}
                    render={({ field }) => (
                      <Input
                        autoFocus
                        type='email'
                        placeholder='john@example.com'
                        invalid={errors.loginEmail && true}
                        {...field}
                      />
                    )}
                  />
                </div>
                <div className='mb-1'>
                  <div className='d-flex justify-content-between'>
                    <Label className='form-label' for='login-password'>
                      Mật khẩu
                    </Label>
                    {/* <Link to='/forgot-password'>
                      <small>Forgot Password?</small>
                    </Link> */}
                  </div>
                  <Controller
                    id='password'
                    name='password'
                    control={control}
                    render={({ field }) => (
                      <InputPasswordToggle className='input-group-merge' invalid={errors.password && true} {...field} />
                    )}
                  />
                </div>
                <div className='form-check mb-1'>
                  <Input type='checkbox' id='remember-me' />
                  <Label className='form-check-label' for='remember-me'>
                    Ghi nhớ đăng nhập
                  </Label>
                </div>
                <Button type='submit' color='primary' block>
                  Đăng nhập
                </Button>
              </Form>
            </Col>
          </Col>
        </Row>
      </div>
    </UILoader>
  )
}

export default Login
